# Windows-compatible version of collectSubmission.sh
# NOTE: DO NOT EDIT THIS FILE-- MAY RESULT IN INCOMPLETE SUBMISSIONS
$ErrorActionPreference = "Stop"

$CODE = @(
    "cs231n/classifiers/k_nearest_neighbor.py"
    "cs231n/classifiers/linear_classifier.py"
    "cs231n/classifiers/softmax.py"
    "cs231n/classifiers/fc_net.py"
    "cs231n/optim.py"
    "cs231n/solver.py"
    "cs231n/layers.py"
)

$NOTEBOOKS = @(
    "knn.ipynb"
    "softmax.ipynb"
    "two_layer_net.ipynb"
    "features.ipynb"
    "FullyConnectedNets.ipynb"
)

$FILES = $CODE + $NOTEBOOKS
$ZIP_FILENAME = "a1_code_submission.zip"
$PDF_FILENAME = "a1_inline_submission.pdf"

# Check all required files exist
foreach ($f in $FILES) {
    if (-not (Test-Path $f)) {
        Write-Host "Required file $f not found, Exiting." -ForegroundColor Red
        exit 1
    }
}

# Collect files to zip: notebooks + all .py files + cs231n/saved, excluding makepdf.py
Write-Host "### Zipping file ###"
if (Test-Path $ZIP_FILENAME) { Remove-Item $ZIP_FILENAME -Force }

$toZip = @()
$toZip += $NOTEBOOKS
$toZip += Get-ChildItem -Recurse -Filter "*.py" |
    Where-Object { $_.Name -ne "makepdf.py" } |
    ForEach-Object { $_.FullName }
if (Test-Path "cs231n/saved") {
    $toZip += Get-ChildItem -Recurse -Path "cs231n/saved" |
        Where-Object { -not $_.PSIsContainer } |
        ForEach-Object { $_.FullName }
}

Compress-Archive -Path $toZip -DestinationPath $ZIP_FILENAME

Write-Host "### Creating PDFs ###"
python makepdf.py --notebooks $NOTEBOOKS --pdf_filename $PDF_FILENAME

Write-Host "### Done! Please submit $ZIP_FILENAME and $PDF_FILENAME to Gradescope. ###"
